// robot_arm_new.scad
// Простая 3D-печатная модель промышленного роботизированного манипулятора
// Под сервоприводы MG996R или SG90, материал: PLA
// Все отдельные детали рассчитаны так, чтобы помещаться на стол 200x200 мм.
// Авторежим по умолчанию показывает раскладку деталей для печати.

$fn = 64;

// ===================== НАСТРОЙКИ =====================
servo_type = "MG996R";     // "MG996R" или "SG90"
view_mode  = "print";      // "print" = детали на столе, "assembled" = собранный вид

// Основные размеры манипулятора
base_diameter = 90;
base_height   = 14;
lower_arm_len = 118;
upper_arm_len = 98;
arm_width     = 28;
arm_thick     = 12;
wall          = 4;
hole_d        = 5.2;       // отверстия под винт M5 / ось
clearance     = 0.5;       // технологический зазор для PLA

// Размеры популярных сервоприводов
function servo_body(t) =
    t == "SG90" ? [23.0, 12.2, 24.5] :   // корпус SG90: X,Y,Z
                  [40.7, 20.2, 39.5];    // корпус MG996R: X,Y,Z

function servo_tabs(t) =
    t == "SG90" ? [32.0, 12.2, 2.5] :    // уши крепления SG90
                  [54.5, 20.2, 2.8];     // уши крепления MG996R

servo = servo_body(servo_type);
tabs  = servo_tabs(servo_type);

// ===================== ВСПОМОГАТЕЛЬНЫЕ МОДУЛИ =====================

// Скругленный прямоугольный брусок, удобный для печати из PLA
module rounded_box(size=[20,20,5], r=3, center=true) {
    x = size[0]; y = size[1]; z = size[2];
    translate(center ? [0,0,0] : [x/2,y/2,z/2])
    hull() {
        for (sx=[-1,1], sy=[-1,1])
            translate([sx*(x/2-r), sy*(y/2-r), 0])
                cylinder(h=z, r=r, center=true);
    }
}

// Отверстие под ось/винт
module axle_hole(depth=80, d=hole_d) {
    rotate([90,0,0]) cylinder(h=depth, d=d, center=true);
}

// Прямоугольное посадочное окно под сервопривод
module servo_cutout(t=servo_type, extra=clearance) {
    s = servo_body(t);
    translate([0,0,0])
        cube([s[0]+extra, s[1]+extra, s[2]+extra], center=true);
}

// Отверстия под уши сервопривода
module servo_mount_holes(t=servo_type) {
    tb = servo_tabs(t);
    spacing = t == "SG90" ? 27.5 : 49.5;
    for (x=[-spacing/2, spacing/2])
        translate([x,0,0])
            cylinder(h=30, d=2.4, center=true);
}

// Рельефные ребра жесткости для индустриального вида
module rib(length=80, width=4, height=5) {
    rounded_box([length, width, height], r=1.5, center=true);
}

// ===================== ДЕТАЛИ =====================

// 1. База: круглая платформа с поворотным сервоприводом внутри
module base_part() {
    // База напоминает поворотный стол промышленного робота
    difference() {
        union() {
            cylinder(h=base_height, d=base_diameter, center=false);
            translate([0,0,base_height])
                cylinder(h=8, d=54, center=false);
            // декоративные ребра на основании
            for (a=[0:60:300])
                rotate([0,0,a])
                    translate([27,0,base_height+4])
                        rounded_box([30,6,8], r=2, center=true);
        }
        // облегчение снизу
        translate([0,0,-1]) cylinder(h=base_height-4, d=base_diameter-16, center=false);
        // центральное отверстие под вал/проводку
        translate([0,0,-1]) cylinder(h=base_height+20, d=12, center=false);
        // отверстия для крепления базы к поверхности
        for (a=[45,135,225,315])
            rotate([0,0,a]) translate([32,0,-1]) cylinder(h=base_height+4, d=4.2, center=false);
    }
}

// 2. Плечевой кронштейн: держит нижнее звено и сервопривод плеча
module shoulder_bracket_part() {
    // П-образная стойка, похожая на шарнир промышленного манипулятора
    s = servo_body(servo_type);
    bracket_w = max(62, tabs[0] + 10);
    bracket_h = s[2] + 24;
    bracket_d = s[1] + 18;

    difference() {
        union() {
            rounded_box([bracket_w, bracket_d, 8], r=4, center=true);
            translate([-bracket_w/2+6,0,bracket_h/2])
                rounded_box([12, bracket_d, bracket_h], r=4, center=true);
            translate([ bracket_w/2-6,0,bracket_h/2])
                rounded_box([12, bracket_d, bracket_h], r=4, center=true);
            translate([0,0,bracket_h+2])
                rounded_box([bracket_w, bracket_d, 8], r=4, center=true);
        }
        // посадочное окно под MG996R/SG90
        translate([0,0,bracket_h/2]) servo_cutout(servo_type, clearance);
        // отверстия крепления сервопривода
        translate([0,0,bracket_h/2 + s[2]/2]) servo_mount_holes(servo_type);
        // ось шарнира плеча
        translate([0,0,bracket_h]) axle_hole(depth=bracket_d+8, d=hole_d);
    }
}

// 3. Нижняя тяга: усиленное звено с облегчением и ребрами
module lower_arm_part() {
    // Длинное звено с двумя проушинами, как у настоящего промышленного робота
    difference() {
        union() {
            // две боковые пластины
            translate([0,-arm_width/2,0]) rounded_box([lower_arm_len, wall, arm_thick], r=3, center=true);
            translate([0, arm_width/2,0]) rounded_box([lower_arm_len, wall, arm_thick], r=3, center=true);
            // круговые бобышки вокруг шарниров
            for (x=[-lower_arm_len/2+12, lower_arm_len/2-12]) {
                translate([x,0,0]) cylinder(h=arm_thick, d=30, center=true);
                translate([x,0,0]) rounded_box([18, arm_width+8, arm_thick], r=4, center=true);
            }
            // диагональные ребра фермы
            translate([0,0,arm_thick/2+2]) rotate([0,0,10]) rib(lower_arm_len-36, 4, 4);
            translate([0,0,arm_thick/2+2]) rotate([0,0,-10]) rib(lower_arm_len-36, 4, 4);
        }
        // отверстия под оси шарниров
        for (x=[-lower_arm_len/2+12, lower_arm_len/2-12])
            translate([x,0,0]) cylinder(h=arm_thick+4, d=hole_d, center=true);
        // центральное облегчение
        rounded_box([lower_arm_len-52, arm_width-10, arm_thick+4], r=8, center=true);
    }
}

// 4. Локтевой кронштейн: переход между нижним и верхним звеном
module elbow_bracket_part() {
    // Компактный шарнир с местом под сервопривод локтя
    s = servo_body(servo_type);
    w = max(58, tabs[0] + 8);
    d = s[1] + 16;
    h = s[2] + 14;

    difference() {
        union() {
            rounded_box([w,d,10], r=4, center=true);
            translate([0,0,h/2]) rounded_box([w,d,h], r=5, center=true);
            translate([-w/2+8,0,h+8]) rounded_box([14,d,18], r=4, center=true);
            translate([ w/2-8,0,h+8]) rounded_box([14,d,18], r=4, center=true);
        }
        translate([0,0,h/2]) servo_cutout(servo_type, clearance);
        translate([0,0,h]) axle_hole(depth=d+10, d=hole_d);
        translate([0,0,h/2 + s[2]/2]) servo_mount_holes(servo_type);
    }
}

// 5. Верхняя тяга: более короткое звено для запястья
module upper_arm_part() {
    // Верхнее звено легче нижнего, но с тем же промышленным языком формы
    difference() {
        union() {
            translate([0,-arm_width/2,0]) rounded_box([upper_arm_len, wall, arm_thick], r=3, center=true);
            translate([0, arm_width/2,0]) rounded_box([upper_arm_len, wall, arm_thick], r=3, center=true);
            for (x=[-upper_arm_len/2+12, upper_arm_len/2-12]) {
                translate([x,0,0]) cylinder(h=arm_thick, d=28, center=true);
                translate([x,0,0]) rounded_box([16, arm_width+6, arm_thick], r=4, center=true);
            }
            translate([0,0,arm_thick/2+2]) rotate([0,0,12]) rib(upper_arm_len-34, 4, 4);
            translate([0,0,arm_thick/2+2]) rotate([0,0,-12]) rib(upper_arm_len-34, 4, 4);
        }
        for (x=[-upper_arm_len/2+12, upper_arm_len/2-12])
            translate([x,0,0]) cylinder(h=arm_thick+4, d=hole_d, center=true);
        rounded_box([upper_arm_len-48, arm_width-10, arm_thick+4], r=7, center=true);
    }
}

// 6. Запястье: маленький кронштейн перед захватом
module wrist_part() {
    // Узел запястья связывает верхнюю тягу и простой захват
    difference() {
        union() {
            rounded_box([46,34,12], r=4, center=true);
            translate([0,0,16]) rounded_box([34,26,20], r=4, center=true);
            translate([-18,0,28]) rounded_box([10,28,16], r=3, center=true);
            translate([ 18,0,28]) rounded_box([10,28,16], r=3, center=true);
        }
        translate([0,0,28]) axle_hole(depth=40, d=hole_d);
        translate([0,0,0]) cylinder(h=18, d=10, center=true);
