    color([0.1,0.1,0.1,0.15])
        translate([0,0,-0.5]) difference() {
            cube([200,200,1], center=true);
            cube([190,190,2], center=true);
        }
}

module assembled_view() {
    // Условный собранный вид: показывает промышленный силуэт манипулятора
    base_part();
    translate([0,0,base_height+4]) shoulder_bracket_part();

    // нижнее звено поднято вперед
    translate([0,0,82]) rotate([0,35,0]) translate([lower_arm_len/2,0,0]) lower_arm_part();

    // локтевой узел
    translate([96,0,150]) rotate([0,20,0]) elbow_bracket_part();

    // верхнее звено
    translate([110,0,170]) rotate([0,-28,0]) translate([upper_arm_len/2,0,0]) upper_arm_part();

    // запястье и захват
    translate([195,0,130]) rotate([0,-10,0]) wrist_part();
    translate([225,0,130]) rotate([0,0,-90]) gripper_part();
}

if (view_mode == "assembled") {
    assembled_view();
} else {
    print_layout();
}

// robot_arm_v4.scad
// Оптимизированная роботизированная рука под 28BYJ-48 + ULN2003
// Единицы: миллиметры. Концепция: лёгкие рычаги, жёсткие коробчатые профили,
// низкий центр масс, прямой привод в суставах и параллелограмм ориентации инструмента.

$fn = 72;

// ------------------------- ПАРАМЕТРЫ -------------------------
// Геометрия двигателя 28BYJ-48
motor_d        = 28;
motor_h        = 19;
shaft_d        = 5;
shaft_l        = 10;
motor_hole_sp  = 35;
motor_ear_d    = 8;

// Плата драйвера ULN2003
board_x = 32;
board_y = 20;
board_z = 2;
board_holes_x = 23;
board_holes_y = 15;

// Рабочая кинематика: высота инструмента ~160 мм от стола.
// При установке на подставку/стол 140-220 мм рабочая зона попадает в 300-400 мм.
base_d = 70;
base_h = 50;
shoulder_z = 86;
lower_len = 108;
upper_len = 78;
lower_ang = 30;   // нижнее звено вверх: меньше момент на плече
upper_ang = -18;  // верхнее звено слегка вниз: рабочая зона PCB/пайка

// Печатные структурные ограничения
wall = 3;         // минимальная стенка 3 мм
arm_w = 18;       // ширина рычага по Y
arm_h = 16;       // высота рычага по Z/локальной оси
rib_t = 3;        // внутренние рёбра 3 мм
joint_d = 34;
link_d = 5;
link_offset_y = 17;

// Расчётные точки в плоскости XZ
shoulder = [0, 0, shoulder_z];
elbow_x  = lower_len * cos(lower_ang);
elbow_z  = shoulder_z + lower_len * sin(lower_ang);
wrist_x  = elbow_x + upper_len * cos(lower_ang + upper_ang);
wrist_z  = elbow_z + upper_len * sin(lower_ang + upper_ang);

// ------------------------- СЛУЖЕБНЫЕ МОДУЛИ -------------------------
module rounded_box(size=[10,10,10], r=2, center=true) {
    // Лёгкое скругление через minkowski; используется умеренно, чтобы файл рендерился быстро.
    minkowski() {
        cube([size[0]-2*r, size[1]-2*r, size[2]-2*r], center=center);
        sphere(r=r, $fn=24);
    }
}

module bolt_hole(d=3.2, h=12) {
    cylinder(d=d, h=h, center=true, $fn=32);
}

module screw_head(d=7, h=2) {
    color("#222222") cylinder(d=d, h=h, center=true, $fn=32);
}

module bearing_ring(od=26, id=12, h=8) {
    // Кольцо под втулку/подшипник: распределяет нагрузку и снижает изгиб оси.
    color("#b8bcc2")
    difference() {
        cylinder(d=od, h=h, center=true);
        cylinder(d=id, h=h+0.4, center=true);
    }
}

// ------------------------- КОМПОНЕНТЫ -------------------------
module motor_28byj(label="28BYJ-48") {
    // Модель двигателя: цилиндрический корпус, монтажные уши 35 мм, вал 5 мм.
    color("#c7cbd1")
    union() {
        cylinder(d=motor_d, h=motor_h, center=true);
        hull() {
            translate([-motor_hole_sp/2, 0, 0]) cylinder(d=motor_ear_d, h=3, center=true);
            translate([ motor_hole_sp/2, 0, 0]) cylinder(d=motor_ear_d, h=3, center=true);
        }
    }
    color("#202327")
    for (x=[-motor_hole_sp/2, motor_hole_sp/2])
        translate([x,0,0]) cylinder(d=3.2, h=4, center=true);

    color("#e1e4e8")
    translate([0,0,motor_h/2 + shaft_l/2]) cylinder(d=shaft_d, h=shaft_l, center=true);

    color("#8d949e")
    translate([0, -motor_d/2-3, 0]) cube([17,5,11], center=true); // кабельный выступ

    // Небольшая метка направления, не влияет на печать.
    color("#4d5662")
    translate([0,0,motor_h/2+0.2]) linear_extrude(height=0.4)
        text(label, size=3.0, halign="center", valign="center");
}

module uln2003_board() {
    // Плата драйвера на базе: короткие провода, меньше паразитных моментов.
    color("#1f7a48") rounded_box([board_x, board_y, board_z], r=0.8, center=true);
    color("#d7d09a")
    for (x=[-board_holes_x/2, board_holes_x/2])
        for (y=[-board_holes_y/2, board_holes_y/2])
            translate([x,y,board_z/2+0.15]) cylinder(d=2.4, h=0.4, center=true, $fn=20);
    color("#151515") translate([-8,0,2.5]) cube([12,7,3], center=true);
    color("#284cff") for (i=[0:3]) translate([6+i*3.2,-6,2.7]) cube([2.2,4,3.4], center=true);
    color("#f1c232") translate([10,6,2.6]) cube([8,5,3.2], center=true);
}

module base_assembly() {
    // Тяжёлая широкая база: центр масс максимально низко, диаметр 70 мм, высота 50 мм.
    color("#6c737d")
    difference() {
        cylinder(d=base_d, h=base_h, center=false);
        // Карман снизу под утяжелитель/стальную шайбу; оставлена 4-мм стенка.
        translate([0,0,4]) cylinder(d=base_d-12, h=18, center=false);
        // Четыре крепёжных отверстия к столу или плите.
        for(a=[45,135,225,315])
            rotate([0,0,a]) translate([base_d/2-12,0,base_h-8]) cylinder(d=4.4, h=18, center=true);
    }

    color("#969da6")
    translate([0,0,base_h]) cylinder(d1=46, d2=34, h=22, center=false);

    // Низкое размещение электроники и противовеса.
    translate([0,-33,14]) rotate([90,0,0]) uln2003_board();
    color("#33383f") translate([0,25,12]) rounded_box([42,10,16], r=2, center=true); // противовес

    // Вилка плечевого узла с двумя щёками: нагрузка не висит консольно на валу.
    color("#8e969f")
    for(y=[-14,14])
        translate([0,y,shoulder_z]) rounded_box([44,wall,42], r=2, center=true);
    translate([0,0,shoulder_z]) bearing_ring(od=38, id=13, h=32);

    // Двигатель плеча расположен на базе/у основания: масса не переносится на локоть.
    translate([0,-29,shoulder_z]) rotate([90,0,0]) motor_28byj("SH");
}

module box_arm(L=100, name="arm") {
    // Коробчатый рычаг с внутренним окном и диагональными рёбрами.
    // Стенка/рёбра >= 3 мм, печатается без тонких слабых мест.
    color("#aeb4bb")
    difference() {
        rounded_box([L, arm_w, arm_h], r=2, center=true);
        rounded_box([L-2*wall-8, arm_w+0.8, arm_h-2*wall], r=1.2, center=true);
        // продольные окна для снижения инерции при сохранении жёсткости
        for(x=[-L/4, L/4])
            translate([x,0,0]) rounded_box([L/4, arm_w+1, arm_h-2*wall-2], r=1.2, center=true);
    }

    // Диагональные рёбра: Х-ферма против кручения.
    color("#8d949e")
    for(s=[-1,1])
        rotate([0,s*atan((arm_h-2*wall)/(L-18)),0])
            cube([L-18, rib_t, rib_t], center=true);

    // Верхняя/нижняя силовые полки.
    color("#c3c8cf")
    for(z=[-(arm_h/2-wall/2), arm_h/2-wall/2])
        translate([0,0,z]) cube([L-8, arm_w-2, wall], center=true);
}

module joint_hub(label="J") {
    // Большой фланец распределяет момент по рычагу, не перегружая вал 28BYJ.
    color("#a5abb3") cylinder(d=joint_d, h=arm_w+6, center=true, $fn=72);
    bearing_ring(od=26, id=8, h=arm_w+8);
    color("#222222")
    for(a=[0,90,180,270])
        rotate([0,0,a]) translate([joint_d/2-6,0,arm_w/2+3.2]) cylinder(d=3, h=1.4, center=true);
    color("#515965")
    translate([0,0,arm_w/2+4.2]) linear_extrude(height=0.4)
        text(label, size=5, halign="center", valign="center");
}

module lower_arm_assembly() {
    // Нижний рычаг длиннее: лёгкий короб + база-привод, минимум массы на конце.
    translate(shoulder)
    rotate([0,-lower_ang,0]) {
        translate([lower_len/2,0,0]) box_arm(lower_len, "lower");
        translate([0,0,0]) joint_hub("SH");
        translate([lower_len,0,0]) joint_hub("EL");

        // Контрбаланс рядом с плечом: уменьшает удерживающий момент двигателя.
        color("#3d4249") translate([-22,0,-10]) rounded_box([24,20,18], r=3, center=true);
    }
}

module upper_arm_assembly() {
    // Верхний рычаг короче и легче; мотор локтя допустим на локте.
    translate([elbow_x,0,elbow_z])
    rotate([0,-(lower_ang+upper_ang),0]) {
        translate([upper_len/2,0,0]) box_arm(upper_len, "upper");
        translate([0,-27,0]) rotate([90,0,0]) motor_28byj("EL");
        translate([upper_len,0,0]) joint_hub("WR");
    }
}

module parallelogram_links() {
    // Параллелограмм удерживает ориентацию площадки инструмента почти постоянной.
    // Две тяги разведены по Y для устойчивости против кручения.
    link_len = sqrt(pow(wrist_x-shoulder[0],2) + pow(wrist_z-shoulder[2],2));
    link_ang = atan2(wrist_z-shoulder[2], wrist_x-shoulder[0]);

    for(y=[-link_offset_y, link_offset_y]) {
        color("#d0d4d9")
        translate([shoulder[0], y, shoulder[2] + 19])
        rotate([0,-link_ang,0])
            translate([link_len/2,0,0]) cylinder(d=link_d, h=link_len, center=true, $fn=24);

        color("#7c838c")
        translate([shoulder[0], y, shoulder[2] + 19]) sphere(d=9, $fn=32);
        color("#7c838c")
        translate([wrist_x, y, wrist_z + 19]) sphere(d=9, $fn=32);
    }
}

module wrist_and_tool() {
    translate([wrist_x,0,wrist_z]) {
        // Пассивная ось запястья с пружинным возвратом.
        color("#a7adb5") rotate([90,0,0]) cylinder(d=24, h=36, center=true);
        color("#222222") rotate([90,0,0]) cylinder(d=8, h=42, center=true);

        // Условная торсионная пружина: визуализация, место под реальную пружину.
        color("#4c535c")
        for(i=[0:7])
            translate([0,-16+i*4.5,0]) rotate([90,0,0]) torus(10, 0.7);

        // Стандартная площадка 50x50 с отверстиями 38x38 под М4.
        translate([28,0,0]) rotate([0,90,0]) tool_plate();
    }
}

module torus(R=10, r=1) {
    rotate_extrude(convexity=8)
        translate([R,0,0]) circle(r=r, $fn=12);
}

module tool_plate() {
    color("#bfc5cc")
    difference() {
        rounded_box([50,50,6], r=3, center=true);
        for(x=[-19,19])
            for(y=[-19,19])
                translate([x,y,0]) cylinder(d=4.3, h=8, center=true, $fn=32); // М4 clearance/thread insert
        translate([0,0,0]) cylinder(d=18, h=8, center=true, $fn=48); // центральное облегчение/кабель
    }
    color("#30343a")
    for(x=[-19,19])
        for(y=[-19,19])
            translate([x,y,3.4]) cylinder(d=7.5, h=1.2, center=true, $fn=32);
}

module load_and_com_markers() {
    // Маркеры анализа масс: визуальные подсказки для настройки противовесов.
    // Синий — ожидаемый общий ЦМ, зелёный — рабочая зона инструмента.
    color([0.1,0.35,1,0.55]) translate([28,0,58]) sphere(d=8, $fn=32);
    color([0.1,0.8,0.2,0.22])
    translate([wrist_x+28,0,wrist_z]) rotate([90,0,0]) cylinder(d=82, h=1.2, center=true, $fn=96);
}

module industrial_arm() {
    base_assembly();
    lower_arm_assembly();
    upper_arm_assembly();
    parallelogram_links();
    wrist_and_tool();
    load_and_com_markers();

    // Небольшие резиновые ножки.
    color("#16181b")
    for(a=[45,135,225,315])
        rotate([0,0,a]) translate([base_d/2-10,0,-2]) cylinder(d=10, h=4, center=false);
}

// ------------------------- СБОРКА -------------------------
// Серебристо-серая промышленная схема: минимум игрушечности, читаемые узлы.
industrial_arm();

// ------------------------- ПРИМЕЧАНИЯ К ФИЗИКЕ -------------------------
// 1) Масса двигателя плеча находится на базе, поэтому плечевой сустав не несёт мотор как консольный груз.
// 2) Нижний рычаг длинный, но коробчатый и облегчённый; рёбра работают на изгиб и кручение.
// 3) Противовес у плеча уменьшает статический момент от нижнего/верхнего звена.
// 4) Локтевой 28BYJ-48 стоит у локтя: верхнее звено короче и легче, момент ниже.
// 5) Параллелограммные тяги разведены по Y, чтобы поддерживать ориентацию инструмента и снижать кручение.
// 6) Все несущие стенки и рёбра заданы не тоньше 3 мм для FDM-печати.

// robot_arm_final.scad
// Чистая реалистичная модель 4-DOF роботизированной руки под 28BYJ-48 + ULN2003
// Все основные детали рассчитаны для печати PLA на столе 200x200 мм.
// Единицы измерения: миллиметры.

$fn = 96;

// ---------------------------
// Параметры электроники
// ---------------------------
motor_d        = 28;   // диаметр 28BYJ-48
motor_h        = 19;   // высота корпуса мотора
shaft_d        = 5;    // вал 5 мм
shaft_len      = 10;
board_x        = 32;   // ULN2003: 32x20x2 мм
board_y        = 20;
board_z        = 2;
board_hole_x   = 23;   // расстояние между отверстиями
board_hole_y   = 15;

// ---------------------------
// Параметры печатных деталей
// ---------------------------
wall           = 3;
clearance      = 0.35; // технологический зазор для PLA
base_d         = 112;
base_h         = 14;
turntable_d    = 72;
turntable_h    = 12;
column_h       = 42;
column_d       = 42;
shoulder_z     = base_h + turntable_h + column_h;

lower_len      = 94;
lower_w        = 28;
lower_h        = 22;
upper_len      = 76;
upper_w        = 23;
upper_h        = 19;
joint_d        = 42;
joint_t        = 20;

// Углы только для красивого собранного вида.
base_angle     = 0;
shoulder_angle = -28;
elbow_angle    = 48;
gripper_angle  = 0;

// Цвета для предпросмотра: серый PLA, темные вставки, синие моторы, зеленая плата.
pla       = [0.78, 0.80, 0.82, 1];
dark      = [0.08, 0.09, 0.10, 1];
metal     = [0.72, 0.72, 0.68, 1];
blueMotor = [0.18, 0.35, 0.82, 1];
greenPCB  = [0.00, 0.42, 0.18, 1];
orange    = [0.95, 0.45, 0.08, 1];

// ---------------------------
// Базовые вспомогательные формы
// ---------------------------
module rounded_box(size=[10,10,10], r=2, center=true) {
    // Скругленная прямоугольная деталь. Радиус ограничен, чтобы не ломать геометрию.
    rr = min(r, min(size[0], min(size[1], size[2]))/2 - 0.01);
    if (center) {
        minkowski() {
            cube([size[0]-2*rr, size[1]-2*rr, size[2]-2*rr], center=true);
            sphere(r=rr);
        }
    } else {
        translate([size[0]/2, size[1]/2, size[2]/2])
            rounded_box(size, rr, true);
    }
}

module screw_hole(d=3.2, h=10) {
    cylinder(d=d, h=h, center=true, $fn=36);
}

module flange(d=46, t=6, holes=4, hole_d=3.2, hole_r=18) {
    // Круглый фланец с крепежными отверстиями под М3.
    difference() {
        cylinder(d=d, h=t, center=true);
        for (a=[0:360/holes:359])
            rotate([0,0,a]) translate([hole_r,0,0]) screw_hole(hole_d, t+1);
        cylinder(d=shaft_d + 0.8, h=t+1, center=true);
    }
}

module ring(d_outer=40, d_inner=29, h=8) {
    difference() {
        cylinder(d=d_outer, h=h, center=true);
        cylinder(d=d_inner, h=h+1, center=true);
    }
}

// ---------------------------
// Визуальные модели покупных компонентов
// ---------------------------
module motor_28byj48() {
    // Упрощенная модель мотора 28BYJ-48 для проверки посадки.
    color(blueMotor)
    union() {
        cylinder(d=motor_d, h=motor_h, center=true);
        translate([0,0,motor_h/2 + 1.5]) cylinder(d=9, h=3, center=true);
        translate([0,0,motor_h/2 + 3 + shaft_len/2])
            color(metal) cylinder(d=shaft_d, h=shaft_len, center=true);
        // Ушки корпуса мотора.
        for (x=[-17.5,17.5])
            translate([x,0,0]) rounded_box([12,8,motor_h*0.82], 2, true);
    }
}

module uln2003_board() {
    // Плата драйвера ULN2003: 32x20x2 мм, отверстия 23x15 мм.
    color(greenPCB)
    difference() {
        rounded_box([board_x, board_y, board_z], 1.2, true);
        for (x=[-board_hole_x/2, board_hole_x/2])
            for (y=[-board_hole_y/2, board_hole_y/2])
                translate([x,y,0]) cylinder(d=2.4, h=board_z+1, center=true, $fn=24);
    }
    color([0.05,0.05,0.05,1])
    translate([-8,0,2]) rounded_box([8,14,4], 0.8, true);
    color([0.9,0.9,0.1,1])
    translate([8,0,2]) rounded_box([9,16,5], 0.8, true);
}

// ---------------------------
// Печатные узлы
// ---------------------------
module base_platform() {
    // Основание: низкий цилиндр, мотор вертикально внутри, сверху поворотный стол.
    color(pla)
    difference() {
        union() {
            cylinder(d=base_d, h=base_h, center=false);
            translate([0,0,base_h]) cylinder(d=turntable_d, h=turntable_h, center=false);
            translate([0,0,base_h + turntable_h]) cylinder(d=column_d, h=column_h, center=false);
            // Ребра жесткости колонны.
            for (a=[0,90,180,270])
                rotate([0,0,a]) translate([column_d/2 + 7,0,base_h + turntable_h + column_h/2])
                    rounded_box([14,7,column_h], 2, true);
        }
        // Карман под мотор в основании.
        translate([0,0,base_h/2]) cylinder(d=motor_d + 2*clearance, h=base_h+2, center=true);
        // Сквозное отверстие под вал.
        translate([0,0,base_h + turntable_h/2]) cylinder(d=shaft_d + 1.0, h=turntable_h + column_h + 4, center=true);
        // Отверстия крепления к столу/основанию.
        for (a=[45,135,225,315])
            rotate([0,0,a]) translate([base_d/2 - 16,0,base_h/2]) screw_hole(3.4, base_h+2);
    }

    // Декоративная темная поворотная шайба.
    color(dark) translate([0,0,base_h + turntable_h + 0.5]) ring(54, 40, 3);

    // Крепление платы ULN2003 сбоку на основании.
    board_mount();

    // Показываем мотор в основании полупрозрачно/как компонент.
    translate([0,0,base_h/2]) motor_28byj48();
}

module board_mount() {
    // Держатель платы ULN2003 с четырьмя стойками.
    color(pla)
    translate([0,-base_d/2 - 12,base_h + 8])
    union() {
        rounded_box([42,8,20], 2, true);
        for (x=[-board_hole_x/2, board_hole_x/2])
            for (z=[-board_hole_y/2, board_hole_y/2])
