module shoulder_yoke() {
    // Вилка плечевого сустава: две щеки с мотором 28BYJ-48 между ними.
    color(pla)
    translate([0,0,shoulder_z])
    difference() {
        union() {
            translate([0,-22,0]) rounded_box([48,10,50], 3, true);
            translate([0, 22,0]) rounded_box([48,10,50], 3, true);
            translate([0,0,-23]) rounded_box([52,54,8], 3, true);
            for (y=[-22,22])
                translate([0,y,0]) rotate([90,0,0]) cylinder(d=joint_d, h=10, center=true);
        }
        // Отверстие оси плеча.
        rotate([90,0,0]) cylinder(d=shaft_d + 0.9, h=70, center=true);
        // Облегчающие отверстия в щеках.
        for (y=[-22,22])
            translate([0,y,0]) rotate([90,0,0]) cylinder(d=24, h=12, center=true);
    }

    // Мотор плеча с осью вдоль Y.
    translate([0,-34,shoulder_z]) rotate([90,0,0]) motor_28byj48();
    color(metal) translate([0,0,shoulder_z]) rotate([90,0,0]) cylinder(d=shaft_d, h=62, center=true);
}

module arm_segment(len=90, w=28, h=22, name="нижнее звено") {
    // Реалистичное прямоугольное звено с округлыми кромками, ребрами и окнами облегчения.
    color(pla)
    difference() {
        union() {
            rounded_box([len, w, h], 4, true);
            // Наружные продольные ребра жесткости.
            translate([0, w/2 + 2.2, 0]) rounded_box([len-10, 4, h+2], 1.5, true);
            translate([0,-w/2 - 2.2, 0]) rounded_box([len-10, 4, h+2], 1.5, true);
            // Боковые фланцы на концах.
            translate([-len/2,0,0]) rotate([90,0,0]) cylinder(d=joint_d, h=joint_t, center=true);
            translate([ len/2,0,0]) rotate([90,0,0]) cylinder(d=joint_d, h=joint_t, center=true);
        }
        // Центральное окно облегчения, чтобы деталь выглядела как печатная ферма.
        rounded_box([len-34, w+8, h-9], 3, true);
        // Отверстия осей на концах.
        for (x=[-len/2, len/2])
            translate([x,0,0]) rotate([90,0,0]) cylinder(d=shaft_d + 0.9, h=w+20, center=true);
        // Дополнительные М3 отверстия вокруг фланцев.
        for (x=[-len/2, len/2])
            for (z=[-12,12])
                translate([x,0,z]) rotate([90,0,0]) cylinder(d=3.2, h=w+22, center=true, $fn=28);
    }
}

module elbow_motor_housing() {
