            rotate([90,0,0]) cylinder(d=48, h=24, center=true);
            translate([0,0,-22]) rounded_box([52,24,10], 3, true);
        }
        rotate([90,0,0]) cylinder(d=motor_d + 2*clearance, h=25, center=true);
        rotate([90,0,0]) cylinder(d=shaft_d + 1.0, h=40, center=true);
        for (a=[45,135,225,315])
            rotate([0,a,0]) translate([17,0,0]) rotate([90,0,0]) cylinder(d=3.2, h=30, center=true, $fn=24);
    }
    rotate([90,0,0]) motor_28byj48();
}

module wrist_and_gripper() {
    // Запястье с маленьким редукторным узлом и параллельным захватом.
