module base_lower_arm() {
    // Ориентация для печати: деталь лежит плоско, высота умеренная
    difference() {
        union() {
            // Широкое круглое основание с крепежными отверстиями
            cylinder(h=10, d=84, center=true);
            translate([0,0,7]) cylinder(h=8, d=58, center=true);

            // Короб под базовый MG996R
            translate([0,0,31]) rounded_box([servo_flange_l+12, servo_w+16, servo_h+10], r=5);

            // Нижнее плечо — две боковые щеки с промышленными ребрами
            for (y=[-18,18]) {
