            translate([0,0,18]) cylinder(h=8, d=34, center=true);
        }

        // Центральное отверстие для оси/кабелей в основании
        cylinder(h=40, d=14, center=true);

        // Отверстия крепления основания к столу или платформе
        translate([0,0,0]) screw_holes_xy(xdist=58, ydist=58, d=4.2, h=30);

        // Карман под базовый сервопривод MG996R
        translate([0,0,31]) mg996r_cutout(extra=servo_clear);

        // Отверстие под вал сервопривода/серво-рычаг сверху
        translate([0,0,57]) cylinder(h=20, d=horn_d, center=true);

        // Облегчающие отверстия в нижнем плече
        for (x=[38,58,78])
            translate([x,0,18]) rotate([90,0,0]) cylinder(h=60, d=18, center=true);

