module upper_arm() {
    difference() {
        union() {
            // Две параллельные боковые балки верхнего плеча
            for (y=[-14,14]) {
                translate([0,y,0]) rounded_box([96,7,22], r=3);
                translate([-34,y,-11]) rib(length=68, height=18, thick=5);
            }

            // Задний и передний шарниры
            translate([-52,0,0]) rotate([90,0,0]) circular_joint(outer_d=42, inner_d=pivot_d, h=34);
            translate([52,0,0]) rotate([90,0,0]) circular_joint(outer_d=40, inner_d=pivot_d, h=34);

            // Верхняя площадка под MG996R для локтевого/кистевого привода
            translate([0,0,19]) rounded_box([servo_flange_l+10, servo_w+14, 12], r=4);
            translate([0,0,43]) rounded_box([servo_l+10, servo_w+12, servo_h+8], r=4);
        }

        // Карман под сервопривод MG996R
        translate([0,0,43]) mg996r_cutout(extra=servo_clear);

        // Посадка под серво-рычаг снизу/сверху
        translate([0,0,18]) cylinder(h=26, d=horn_d, center=true);

        // Сквозные отверстия шарниров
        for (x=[-52,52])
            translate([x,0,0]) rotate([90,0,0]) cylinder(h=54, d=pivot_d, center=true);

