} else if (part == "motor_flange_2d") {
    motor_flange_2d();
} else if (part == "nano_standoffs_2d") {
    nano_standoffs_2d();
} else {
    // Все проекции для превью
    translate([0, 0]) base_plate_2d();
    translate([case_w + 30, 0]) case_main_2d();
    translate([0, case_d + 30]) case_lid_2d();
