    translate([2*(case_w + 30), case_d/2]) nano_standoffs_2d();
}

// PRO BASE BLOCK — раздельный экспорт STL
// Arduino Nano + 28BYJ-48 + ULN2003

// ========== КОМПОНЕНТЫ ==========
nano_w = 18;
nano_l = 45;
nano_h = 4;
nano_hole_sp_x = 29;
nano_hole_sp_y = 15;

motor_d = 28;
motor_h = 19;
shaft_d = 5;
shaft_l = 10;
flange_sp = 35;

uln_w = 32;
uln_h = 20;
uln_th = 2;
uln_sp_x = 23;
uln_sp_y = 15;

// ========== КОРПУС ==========
case_w = 68;
case_d = 78;
case_h = 32;
wall = 3;
m3_d = 3;

$fn = 100;

// ========== 1. ОПОРНАЯ ПЛИТА ==========
module base_plate() {
    color("DimGray")
    difference() {
        cube([case_w + 12, case_d + 12, 5]);
        for (x = [-1, 1], y = [-1, 1])
            translate([x * (case_w/2 + 4), y * (case_d/2 + 4), -1])
                cylinder(h=7, d=m3_d);
    }
}

// ========== 2. ОСНОВНОЙ КОРПУС ==========
module case_main() {
    color("DimGray")
    difference() {
        cube([case_w, case_d, case_h]);
        // Внутренняя полость
        translate([wall, wall, wall])
            cube([case_w - 2*wall, case_d - 2*wall, case_h]);
        // Вырез под мотор (сверху)
        translate([case_w/2, case_d/2, case_h - wall])
            cylinder(h=wall + 3, d=motor_d + 2);
        // 4 отверстия справа
        for (y = [10, 18, 26, 34])
            translate([case_w - wall/2, y, case_h/2])
                rotate([0, 90, 0])
                    cylinder(h=wall + 3, d=m3_d);
        // Жёлтая полоса сверху
        translate([wall, case_d - wall - 4, case_h - wall])
            cube([case_w - 2*wall, 4, 2]);
        // Окошко спереди
        translate([-1, case_d/2 - 10, case_h/2 - 8])
            cube([wall + 2, 20, 16]);
        // USB
        translate([-1, case_d/2 + 15, case_h/2])
            cube([wall + 2, 6, 4]);
    }
    // Зелёная плата внутри
    color("Green")
    translate([wall + 2, case_d/2 - 8, case_h/2 - 6])
        cube([case_w - 2*wall - 4, 16, 12]);
}

// ========== 3. КРЫШКА ==========
module case_lid() {
    color("DimGray")
    difference() {
        cube([case_w, case_d, wall]);
        for (x = [6, case_w - 6], y = [6, case_d - 6])
            translate([x, y, -1])
                cylinder(h=wall + 2, d=m3_d);
        translate([case_w/2 - 10, case_d/2, wall/2])
            cylinder(h=wall + 2, d=4);
        translate([case_w/2 + 10, case_d/2, wall/2])
            cylinder(h=wall + 2, d=4);
    }
}

// ========== 4. ФЛАНЕЦ МОТОРА ==========
module motor_flange() {
    color("DimGray")
    difference() {
        cylinder(h=wall + 5, d=motor_d + 16);
        translate([0, 0, -1])
            cylinder(h=wall + 7, d=shaft_d + 3);
        translate([0, 0, wall + 3])
            cylinder(h=4, d=8);
        for (a = [0:90:359])
            rotate([0, 0, a])
                translate([flange_sp/2, 0, 2.5])
                    cylinder(h=6, d=3);
    }
    // Втулка
    color("Silver")
    translate([0, 0, wall + 3])
        cylinder(h=3, d=6);
}

// ========== 5. СТОЙКИ ДЛЯ ARDUINO NANO ==========
module nano_standoffs() {
    color("Silver")
    for (x = [-1, 1], y = [-1, 1])
        translate([x * nano_hole_sp_x/2, y * nano_hole_sp_y/2, 0])
            cylinder(h=6, d=4);
}

// ========== 6. КРЕПЛЕНИЯ ULN2003 ==========
module uln2003_brackets() {
    color("Silver")
    for (x = [-1, 1], y = [-1, 1])
        translate([x * uln_sp_x/2, y * uln_sp_y/2, 0])
            cylinder(h=4, d=3);
}

// ========== УПРАВЛЕНИЕ ЭКСПОРТОМ ==========
// По умолчанию показываем всё для превью
part = "all";

// Для экспорта конкретной детали используй:
// openscad -o деталь.stl -D 'part="base_plate"' model.scad

if (part == "base_plate") {
    base_plate();
} else if (part == "case_main") {
    case_main();
} else if (part == "case_lid") {
    case_lid();
} else if (part == "motor_flange") {
    motor_flange();
} else if (part == "nano_standoffs") {
    nano_standoffs();
} else if (part == "uln2003_brackets") {
    uln2003_brackets();
} else {
    // Всё вместе для превью
    translate([0, 0, 0]) base_plate();
    translate([0, 0, 5]) case_main();
    translate([0, 0, 5 + case_h - wall]) case_lid();
    translate([0, 0, 5 - wall - 5]) motor_flange();
}

// Robot Arm v1.0 — for 28BYJ-48 stepper motors + ULN2003
// Parametric design

// ========== MOTOR PARAMETERS (28BYJ-48) ==========
motor_diameter = 28;
motor_height = 19;
motor_shaft_dia = 5;
motor_shaft_length = 10;
motor_hole_spacing = 35;  // mounting holes

// ========== ULN2003 BOARD PARAMETERS ==========
driver_width = 32;
driver_height = 20;
driver_thickness = 2;
driver_hole_dia = 3;
driver_hole_spacing_x = 23;
driver_hole_spacing_y = 15;

// ========== ARM SEGMENT PARAMETERS ==========
base_height = 40;
lower_arm_length = 80;
lower_arm_width = 25;
lower_arm_thickness = 8;

upper_arm_length = 70;
upper_arm_width = 20;
upper_arm_thickness = 6;

gripper_width = 40;
gripper_depth = 15;
finger_length = 30;
finger_gap = 5;

// ========== QUALITY ==========
$fn = 50;

// ========== BASE MODULE ==========
module base() {
    // Main cylindrical base
    cylinder(h=base_height, d=motor_diameter + 20);

    // Top platform for motor
    translate([0, 0, base_height])
        cylinder(h=5, d=motor_diameter + 10);
}

// ========== MOTOR HOLDER ==========
module motor_holder(height=30) {
    difference() {
        // Outer cylinder
        cylinder(h=height, d=motor_diameter + 16);

        // Motor cavity (hollow inside)
        translate([0, 0, -1])
            cylinder(h=height + 2, d=motor_diameter + 2);

        // Motor shaft hole
        translate([0, 0, height])
            cylinder(h=motor_shaft_length + 5, d=motor_shaft_dia);
    }

    // Mounting flanges with holes
    difference() {
        translate([0, 0, height/2])
            cube([motor_hole_spacing + 10, motor_hole_spacing + 10, 4], center=true);

        // 4 mounting holes
        for (x = [-1, 1], y = [-1, 1])
            translate([x * motor_hole_spacing/2, y * motor_hole_spacing/2, height/2])
                cylinder(h=5, d=3);
    }
}

// ========== MOTOR WITH SHAFT ==========
module stepper_motor_28byj48() {
    color("dimgray")
    difference() {
        cylinder(h=motor_height, d=motor_diameter);
        // Shaft hole
        translate([0, 0, motor_height - 1])
            cylinder(h=motor_shaft_length + 2, d=motor_shaft_dia);
    }
    // Shaft
    color("silver")
    translate([0, 0, motor_height])
        cylinder(h=motor_shaft_length, d=motor_shaft_dia);

    // Connector
    translate([0, -motor_diameter/2 - 3, motor_height/2])
        cube([15, 6, 8], center=true);
}

// ========== ULN2003 DRIVER BOARD ==========
module uln2003_board() {
    color("green")
    difference() {
        cube([driver_width, driver_height, driver_thickness]);

        // 4 mounting holes
        for (x = [-1, 1], y = [-1, 1])
            translate([driver_width/2 + x * driver_hole_spacing_x/2, 
                       driver_height/2 + y * driver_hole_spacing_y/2, -1])
                cylinder(h=driver_thickness + 2, d=driver_hole_dia);
    }

    // Chip
    translate([-driver_width/2 + 5, 0, driver_thickness + 1])
        cube([10, 6, 3]);
}

// ========== ARM SEGMENT ==========
module arm_segment(length, width, thickness) {
    color("lightslategray")
    difference() {
        // Main body
        translate([0, 0, thickness/2])
            cube([length, width, thickness], center=true);

        // Lightening holes
        for (i = [-1, 0, 1])
            translate([i * length/4, 0, thickness/2])
                cube([length/5, width/3, thickness + 2], center=true);
    }

    // Side brackets for motor mount
    translate([-length/2 + 10, width/2 - 2, thickness/2])
        cube([20, 4, thickness + 4]);
    translate([-length/2 + 10, -width/2 + 2, thickness/2])
        cube([20, 4, thickness + 4]);

    // Motor mount shaft
    translate([-length/2 + 5, 0, thickness/2])
        cylinder(h=thickness + 8, d=8);
}

// ========== GRIPPER ==========
module gripper() {
    // Palm
    color("lightslategray")
    translate([0, 0, gripper_depth/2])
        cube([gripper_width, gripper_depth, gripper_depth], center=true);

    // Fingers
    translate([-gripper_width/2 + finger_gap/2, gripper_depth/2, gripper_depth/2])
        cube([finger_gap, finger_length, 4], center=true);
    translate([gripper_width/2 - finger_gap/2, gripper_depth/2, gripper_depth/2])
        cube([finger_gap, finger_length, 4], center=true);

    // Finger tips (curved)
    translate([-gripper_width/2 + finger_gap/2, gripper_depth/2 + finger_length - 5, gripper_depth/2])
        cylinder(h=4, d=8);
    translate([gripper_width/2 - finger_gap/2, gripper_depth/2 + finger_length - 5, gripper_depth/2])
        cylinder(h=4, d=8);
}

// ========== MOUNTING BRACKET ==========
module bracket(width, height, thickness=4) {
    difference() {
        color("silver")
        translate([0, 0, thickness/2])
            cube([width, height, thickness], center=true);

        // Screw holes
        translate([-width/2 + 5, -height/2 + 5, -1])
            cylinder(h=thickness + 2, d=3);
        translate([width/2 - 5, -height/2 + 5, -1])
            cylinder(h=thickness + 2, d=3);
        translate([-width/2 + 5, height/2 - 5, -1])
            cylinder(h=thickness + 2, d=3);
        translate([width/2 - 5, height/2 - 5, -1])
            cylinder(h=thickness + 2, d=3);
    }
}

// ========== ASSEMBLY ==========
// Uncomment to see full assembly

// BASE
translate([0, 0, 0])
    base();

// MOTOR 1 (base rotation)
translate([0, 0, base_height + 2])
    motor_holder(height=20);

translate([0, 0, base_height + 22])
    stepper_motor_28byj48();

// LOWER ARM
translate([0, 0, base_height + 22 + motor_height + 5])
    arm_segment(lower_arm_length, lower_arm_width, lower_arm_thickness);

// MOTOR 2 (elbow joint)
translate([lower_arm_length/2 - 5, 0, base_height + 22 + motor_height + 5])
    motor_holder(height=15);

translate([lower_arm_length/2 - 5, 0, base_height + 22 + motor_height + 5 + 15])
    stepper_motor_28byj48();

// UPPER ARM
translate([lower_arm_length/2 - 5, 0, base_height + 22 + motor_height + 5 + 15 + motor_height + 3])
    arm_segment(upper_arm_length, upper_arm_width, upper_arm_thickness);

// GRIPPER (attached to upper arm end)
translate([lower_arm_length/2 - 5 + upper_arm_length/2 - 5, 0, 
           base_height + 22 + motor_height + 5 + 15 + motor_height + 3])
    gripper();

