// Robot Arm v2.0 — для 28BYJ-48 + ULN2003
// Красивый реалистичный дизайн

// ========== ПАРАМЕТРЫ МОТОРА 28BYJ-48 ==========
motor_d = 28;      // диаметр корпуса
motor_h = 19;      // высота корпуса
shaft_d = 5;       // диаметр вала
shaft_l = 10;      // длина вала
flange_w = 35;     // расстояние между крепёжными отверстиями

// ========== ПАРАМЕТРЫ ПЛАТЫ ULN2003 ==========
driver_w = 32;
driver_h = 20;
driver_th = 2;
hole_sp_x = 23;
hole_sp_y = 15;

// ========== ПАРАМЕТРЫ СУСТАВОВ ==========
base_h = 45;
base_d = 60;
lower_arm_l = 90;
lower_arm_w = 30;
lower_arm_t = 10;
upper_arm_l = 70;
upper_arm_w = 25;
upper_arm_t = 8;
gripper_w = 35;
gripper_d = 20;
finger_l = 35;
finger_gap = 6;

// Качество
$fn = 80;

// ========== ОСНОВАНИЕ ==========
module base() {
    // Цилиндрическое основание
    color("silver")
    difference() {
        cylinder(h=base_h, d=base_d);
        // Вырез снизу для веса
        translate([0, 0, -1])
            cylinder(h=base_h/2 + 2, d=base_d - 15);
        // Центральное отверстие для вала мотора
        translate([0, 0, base_h - 5])
            cylinder(h=10, d=shaft_d + 2);
    }

    // Верхний фланец для мотора
    color("dimgray")
    translate([0, 0, base_h])
        difference() {
            cylinder(h=8, d=motor_d + 12);
            translate([0, 0, -1])
                cylinder(h=10, d=motor_d + 2);
            // Крепёжные отверстия
            for (a = [0:90:359])
                rotate([0, 0, a])
                    translate([flange_w/2, 0, 4])
                        cylinder(h=6, d=3);
        }
}

// ========== ДЕРЖАТЕЛЬ МОТОРА ==========
module motor_holder(h=25) {
    color("silver")
    difference() {
        union() {
            // Цилиндрический корпус
            cylinder(h=h, d=motor_d + 14);
            // Фланцы по бокам
            translate([-(motor_d + 14)/2 - 3, -(flange_w)/2, h/2 - 4])
                cube([motor_d + 14 + 6, flange_w, 8]);
        }
        // Отверстие под мотор
        translate([0, 0, -1])
            cylinder(h=h + 2, d=motor_d + 1);
        // Отверстие под вал
        translate([0, 0, h])
            cylinder(h=shaft_l + 3, d=shaft_d);
        // Крепёжные отверстия на фланцах
        for (x = [-flange_w/2, flange_w/2], y = [-flange_w/2, flange_w/2])
            translate([x, y, h/2])
                cylinder(h=10, d=3);
    }
}

// ========== СЕРВО МОТОР 28BYJ-48 ==========
module stepper_28byj48() {
    // Корпус мотора
    color("dimgray")
    difference() {
        cylinder(h=motor_h, d=motor_d);
        translate([0, 0, motor_h - 1])
            cylinder(h=shaft_l + 2, d=shaft_d);
    }
    // Вал
    color("silver")
    translate([0, 0, motor_h])
        cylinder(h=shaft_l, d=shaft_d);
    // Выступы крепления
    for (a = [0:90:359])
        rotate([0, 0, a])
            translate([motor_d/2 - 2, 0, motor_h/2])
                cylinder(h=3, d=6);
}

// ========== ПЛАТА ULN2003 ==========
module uln2003() {
    color("green")
    difference() {
        cube([driver_w, driver_h, driver_th]);
        // Крепёжные отверстия
        for (x = [-1, 1], y = [-1, 1])
            translate([driver_w/2 + x * hole_sp_x/2, driver_h/2 + y * hole_sp_y/2, -1])
                cylinder(h=driver_th + 2, d=3);
    }
    // Микросхема ULN2003
    color("black")
    translate([-driver_w/2 + 4, 0, driver_th])
        cube([8, 6, 3]);
}

// ========== НИЖНЕЕ ПЛЕЧО ==========
module lower_arm() {
    color("gold")
    difference() {
        // Основа плеча - прямоугольная с закруглением
        translate([0, 0, lower_arm_t/2])
            cube([lower_arm_l, lower_arm_w, lower_arm_t], center=true);
        // Вырез под установку мотора сбоку
        translate([lower_arm_l/2 - 20, 0, -1])
            cylinder(h=lower_arm_t + 4, d=motor_d + 4);
        // Облегчение
        for (i = [-1, 0, 1])
            translate([i * lower_arm_l/4, 0, lower_arm_t/2])
                cube([lower_arm_l/6, lower_arm_w/2.5, lower_arm_t + 2], center=true);
    }
    // Боковые ребра жесткости
    translate([-lower_arm_l/2 + 8, lower_arm_w/2 - 3, lower_arm_t/2])
        cube([16, 6, lower_arm_t + 6]);
    translate([-lower_arm_l/2 + 8, -lower_arm_w/2 + 3, lower_arm_t/2])
        cube([16, 6, lower_arm_t + 6]);
    // Ось сустава
    translate([-lower_arm_l/2 + 5, 0, lower_arm_t/2])
        cylinder(h=lower_arm_w + 8, d=8);
}

// ========== ВЕРХНЕЕ ПЛЕЧО ==========
module upper_arm() {
    color("gold")
    difference() {
        translate([0, 0, upper_arm_t/2])
            cube([upper_arm_l, upper_arm_w, upper_arm_t], center=true);
        // Вырез под мотор
        translate([upper_arm_l/2 - 15, 0, -1])
            cylinder(h=upper_arm_t + 4, d=motor_d + 2);
        // Облегчение
        for (i = [-1, 0, 1])
            translate([i * upper_arm_l/4, 0, upper_arm_t/2])
                cube([upper_arm_l/6, upper_arm_w/2.5, upper_arm_t + 2], center=true);
    }
    // Ребра
    translate([-upper_arm_l/2 + 6, upper_arm_w/2 - 2.5, upper_arm_t/2])
        cube([12, 5, upper_arm_t + 5]);
    translate([-upper_arm_l/2 + 6, -upper_arm_w/2 + 2.5, upper_arm_t/2])
        cube([12, 5, upper_arm_t + 5]);
    // Ось
    translate([-upper_arm_l/2 + 4, 0, upper_arm_t/2])
        cylinder(h=upper_arm_w + 6, d=6);
}

// ========== ГРИППЕР (захват) ==========
module gripper() {
    // Основа
    color("gold")
    translate([0, 0, gripper_d/2])
        cube([gripper_w, gripper_d, gripper_d], center=true);
    // Левая клешня
    translate([-gripper_w/2 + finger_gap/2, gripper_d/2, gripper_d/2])
        cube([finger_gap, finger_l, 5], center=true);
    // Правая клешня
    translate([gripper_w/2 - finger_gap/2, gripper_d/2, gripper_d/2])
        cube([finger_gap, finger_l, 5], center=true);
    // Кончики пальцев - закруглённые
    translate([-gripper_w/2 + finger_gap/2, gripper_d/2 + finger_l/2, gripper_d/2])
        sphere(d=8);
    translate([gripper_w/2 - finger_gap/2, gripper_d/2 + finger_l/2, gripper_d/2])
        sphere(d=8);
}

// ========== КРЕПЁЖНЫЙ УГОЛОК ==========
module bracket(w, h) {
    color("silver")
    difference() {
        translate([0, 0, 3])
            cube([w, h, 6], center=true);
        // Винтовые отверстия по углам
        for (x = [-w/2 + 5, w/2 - 5], y = [-h/2 + 5, h/2 - 5])
            translate([x, y, -1])
                cylinder(h=10, d=3);
    }
}

// ========== СБОРКА ==========
// База
translate([0, 0, 0])
    base();

// Мотор вращения базы
translate([0, 0, base_h + 2])
    motor_holder(20);
translate([0, 0, base_h + 22])
    stepper_28byj48();

// Плата управления на боковой стенке
translate([-(base_d/2 + driver_w/2 + 2), 0, base_h/2])
    rotate([0, 90, 0])
        uln2003();

// Нижнее плечо
translate([0, 0, base_h + 22 + motor_h + 5])
    lower_arm();

// Мотор локтя
translate([lower_arm_l/2 - 5, 0, base_h + 22 + motor_h + 5])
    motor_holder(15);
translate([lower_arm_l/2 - 5, 0, base_h + 22 + motor_h + 5 + 15])
    stepper_28byj48();

// Верхнее плечо
translate([lower_arm_l/2 - 5, 0, base_h + 22 + motor_h + 5 + 15 + motor_h + 3])
    upper_arm();

// Гриппер
translate([lower_arm_l/2 - 5 + upper_arm_l/2 - 5, 0, 
           base_h + 22 + motor_h + 5 + 15 + motor_h + 3])
    gripper();

