// Robot Arm v3.0 — для 28BYJ-48 + ULN2003 + УНИВЕРСАЛЬНОЕ КРЕПЛЕНИЕ
// Манипулятор с площадкой для насадок

// ========== ПАРАМЕТРЫ МОТОРА 28BYJ-48 ==========
motor_d = 28;
motor_h = 19;
shaft_d = 5;
shaft_l = 10;
flange_w = 35;

// ========== ПАРАМЕТРЫ ПЛАТЫ ULN2003 ==========
driver_w = 32;
driver_h = 20;
driver_th = 2;
hole_sp_x = 23;
hole_sp_y = 15;

// ========== ПАРАМЕТРЫ СУСТАВОВ ==========
base_h = 50;
base_d = 65;
lower_arm_l = 85;
lower_arm_w = 30;
lower_arm_t = 10;
upper_arm_l = 65;
upper_arm_w = 25;
upper_arm_t = 8;

// ========== УНИВЕРСАЛЬНАЯ ПЛАТФОРМА ==========
// Стандартный крепёж для насадок: паяльник, гравёр, etc.
plate_w = 50;      // ширина площадки
plate_d = 50;      // глубина площадки
plate_h = 6;       // толщина
mount_holes = 4;   // количество отверстий по углам
mount_dia = 4;     // диаметр отверстий
mount_spacing = 38; // расстояние между отверстиями (по центрам)

// ========== КАЧЕСТВО ==========
$fn = 100;

// ========== ОСНОВАНИЕ ==========
module base() {
    color("silver")
    difference() {
        // Цилиндрический корпус
        cylinder(h=base_h, d=base_d);
        // Вырез снизу для веса
        translate([0, 0, -1])
            cylinder(h=base_h/2 + 2, d=base_d - 18);
        // Отверстие под вал мотора
        translate([0, 0, base_h - 6])
            cylinder(h=12, d=shaft_d + 3);
    }

    // Верхний фланец с крепежом
    color("dimgray")
    translate([0, 0, base_h])
        difference() {
            cylinder(h=10, d=motor_d + 14);
            translate([0, 0, -1])
                cylinder(h=12, d=motor_d + 2);
            for (a = [0:90:359])
                rotate([0, 0, a])
                    translate([flange_w/2, 0, 5])
                        cylinder(h=8, d=3);
        }

    // Ребро жесткости
    translate([-5, -base_d/2 + 3, base_h/2])
        cube([10, base_d - 6, base_h - 10]);
}

// ========== ДЕРЖАТЕЛЬ МОТОРА ==========
module motor_holder(h=25) {
    color("silver")
    difference() {
        union() {
            cylinder(h=h, d=motor_d + 16);
            translate([-(motor_d + 16)/2 - 4, -flange_w/2, h/2 - 5])
                cube([motor_d + 16 + 8, flange_w, 10]);
        }
        translate([0, 0, -1])
            cylinder(h=h + 2, d=motor_d + 1);
        translate([0, 0, h])
            cylinder(h=shaft_l + 4, d=shaft_d);
        for (x = [-flange_w/2, flange_w/2], y = [-flange_w/2, flange_w/2])
            translate([x, y, h/2])
                cylinder(h=12, d=3);
    }
}

// ========== МОТОР 28BYJ-48 ==========
module stepper_28byj48() {
    color("dimgray")
    difference() {
        cylinder(h=motor_h, d=motor_d);
        translate([0, 0, motor_h - 1])
            cylinder(h=shaft_l + 2, d=shaft_d);
    }
    color("silver")
    translate([0, 0, motor_h])
        cylinder(h=shaft_l, d=shaft_d);
    for (a = [0:90:359])
        rotate([0, 0, a])
            translate([motor_d/2 - 2, 0, motor_h/2])
                cylinder(h=3, d=5);
}

// ========== ULN2003 ==========
module uln2003() {
    color("green")
    difference() {
        cube([driver_w, driver_h, driver_th]);
        for (x = [-1, 1], y = [-1, 1])
            translate([driver_w/2 + x * hole_sp_x/2, driver_h/2 + y * hole_sp_y/2, -1])
                cylinder(h=driver_th + 2, d=2.5);
    }
    color("black")
    translate([-driver_w/2 + 4, 0, driver_th])
        cube([8, 6, 3]);
}

// ========== НИЖНЕЕ ПЛЕЧО ==========
module lower_arm() {
    color("gold")
    difference() {
        translate([0, 0, lower_arm_t/2])
            cube([lower_arm_l, lower_arm_w, lower_arm_t], center=true);
        // Вырез под мотор
        translate([lower_arm_l/2 - 18, 0, -1])
            cylinder(h=lower_arm_t + 4, d=motor_d + 5);
        // Облегчение
        for (i = [-1, 0, 1])
            translate([i * lower_arm_l/4, 0, lower_arm_t/2])
                cube([lower_arm_l/6, lower_arm_w/2.5, lower_arm_t + 2], center=true);
    }
    // Боковые ребра
    translate([-lower_arm_l/2 + 8, lower_arm_w/2 - 3, lower_arm_t/2])
        cube([18, 6, lower_arm_t + 8]);
    translate([-lower_arm_l/2 + 8, -lower_arm_w/2 + 3, lower_arm_t/2])
        cube([18, 6, lower_arm_t + 8]);
    // Ось сустава
    translate([-lower_arm_l/2 + 5, 0, lower_arm_t/2])
        cylinder(h=lower_arm_w + 10, d=10);
}

// ========== ВЕРХНЕЕ ПЛЕЧО ==========
module upper_arm() {
    color("gold")
    difference() {
        translate([0, 0, upper_arm_t/2])
            cube([upper_arm_l, upper_arm_w, upper_arm_t], center=true);
        translate([upper_arm_l/2 - 14, 0, -1])
            cylinder(h=upper_arm_t + 4, d=motor_d + 3);
        for (i = [-1, 0, 1])
            translate([i * upper_arm_l/4, 0, upper_arm_t/2])
                cube([upper_arm_l/6, upper_arm_w/2.5, upper_arm_t + 2], center=true);
    }
    translate([-upper_arm_l/2 + 6, upper_arm_w/2 - 2.5, upper_arm_t/2])
        cube([14, 5, upper_arm_t + 6]);
    translate([-upper_arm_l/2 + 6, -upper_arm_w/2 + 2.5, upper_arm_t/2])
        cube([14, 5, upper_arm_t + 6]);
    translate([-upper_arm_l/2 + 4, 0, upper_arm_t/2])
        cylinder(h=upper_arm_w + 8, d=8);
}

// ========== УНИВЕРСАЛЬНАЯ МОНТАЖНАЯ ПЛАТФОРМА ==========
module tool_mount() {
    // Основная площадка
    color("silver")
    difference() {
        cube([plate_w, plate_d, plate_h]);
        // Отверстия по углам для крепления насадок
        for (x = [-mount_spacing/2, mount_spacing/2], y = [-mount_spacing/2, mount_spacing/2])
            translate([plate_w/2 + x, plate_d/2 + y, -1])
                cylinder(h=plate_h + 2, d=mount_dia);
        // Центральный вырез (можно вставить вал)
        translate([0, 0, -1])
            cylinder(h=plate_h + 2, d=8);
    }

    // Резьбовые втулки для надёжного крепления
    color("dimgray")
    for (x = [-mount_spacing/2, mount_spacing/2], y = [-mount_spacing/2, mount_spacing/2])
        translate([plate_w/2 + x, plate_d/2 + y, plate_h])
            cylinder(h=8, d=mount_dia + 2);

    // Маленькие направляющие для позиционирования
    translate([-plate_w/2 + 5, 0, plate_h])
        cube([10, 3, 3]);
    translate([plate_w/2 - 15, 0, plate_h])
        cube([10, 3, 3]);
}

// ========== ПРОСТОЙ ЗАХВАТ (демо) ==========
module simple_gripper() {
    color("gold")
    translate([0, 0, 10])
        cube([40, 15, 15], center=true);
    // Пальцы
    translate([-10, 15, 10])
        cube([5, 30, 5]);
    translate([10, 15, 10])
        cube([5, 30, 5]);
}

// ========== СБОРКА ==========
// База
translate([0, 0, 0])
    base();

// Мотор базы
translate([0, 0, base_h + 2])
    motor_holder(22);
translate([0, 0, base_h + 24])
    stepper_28byj48();

// Плата на боковой стенке
translate([-(base_d/2 + driver_w/2 + 2), 0, base_h/2])
    rotate([0, 90, 0])
        uln2003();

// Нижнее плечо
translate([0, 0, base_h + 24 + motor_h + 5])
    lower_arm();

// Мотор локтя
translate([lower_arm_l/2 - 5, 0, base_h + 24 + motor_h + 5])
    motor_holder(18);
translate([lower_arm_l/2 - 5, 0, base_h + 24 + motor_h + 5 + 18])
    stepper_28byj48();

// Верхнее плечо
translate([lower_arm_l/2 - 5, 0, base_h + 24 + motor_h + 5 + 18 + motor_h + 4])
    upper_arm();

// МОНТАЖНАЯ ПЛАТФОРМА (вместо захвата — сюда крепится паяльник и др.)
translate([lower_arm_l/2 - 5 + upper_arm_l/2 - 5, 0, 
           base_h + 24 + motor_h + 5 + 18 + motor_h + 4])
    tool_mount();

// ========== ДЛЯ ПЕЧАТИ: отдельные детали ==========
