// Robot Arm v4.0 — ОПТИМИЗИРОВАННЫЙ ДИЗАЙН
// ФИЗИКА: моторы на основании, минимум инерции, максимум КПД
// Для 28BYJ-48 + ULN2003

// ========== ПАРАМЕТРЫ МОТОРА 28BYJ-48 ==========
// Технические характеристики:
// Удерживающий момент: ~0.3-0.5 Нм (3-5 кг*см)
// Требует минимизации нагрузки на плечи
motor_d = 28;
motor_h = 19;
shaft_d = 5;
shaft_l = 10;
flange_w = 35;
motor_mass = 0.04; // кг (примерно 40г)

// ========== ПАРАМЕТРЫ ПЛАТЫ ULN2003 ==========
driver_w = 32;
driver_h = 20;
driver_th = 2;

// ========== ОПТИМИЗИРОВАННЫЕ ПАРАМЕТРЫ ==========
// Анализ КПД:
// - Плечо создаёт момент: F * L
// - 28BYJ-48 может держать ~300-500 Нмм (0.3-0.5 Нм)
// - При плече 80мм нагрузка не более 400г на конце
// - При плече 60мм нагрузка не более 600г

base_h = 55;         // Высокое основание для устойчивости
base_d = 70;          // Широкое основание (низкий ЦМ)
lower_arm_l = 75;     // Оптимальная длина нижнего плеча
lower_arm_w = 28;     // Ширина для жесткости
lower_arm_t = 8;      // Толщина
upper_arm_l = 55;     // Короче = меньше момент
upper_arm_w = 22;
upper_arm_t = 7;

// Крепление насадок
plate_w = 50;
plate_d = 50;
mount_sp = 38;

// ========== КАЧЕСТВО ==========
$fn = 100;

// ========== МОДУЛИ ==========

// ОСНОВАНИЕ — тяжёлое, низкий центр масс
module base() {
    color("silver")
    difference() {
        // Нижняя часть — широкий конус для устойчивости
        cylinder(h=base_h, d=base_d, center=false);
        // Вырез снизу (экономия пластика без потери устойчивости)
        translate([0, 0, 3])
            cylinder(h=base_h/2, d=base_d - 20);
        // Отверстие под вал мотора
        translate([0, 0, base_h - 8])
            cylinder(h=15, d=shaft_d + 3);
    }

    // Верхний фланец
    color("dimgray")
    translate([0, 0, base_h])
        difference() {
            cylinder(h=10, d=motor_d + 16);
            translate([0, 0, -1])
                cylinder(h=12, d=motor_d + 2);
            for(a=[0:90:359])
                rotate([0,0,a])
                    translate([flange_w/2, 0, 5])
                        cylinder(h=8, d=3);
        }
}

// ДЕРЖАТЕЛЬ МОТОРА — фланцевый
module motor_holder(h=25) {
    color("silver")
    difference() {
        union() {
            cylinder(h=h, d=motor_d + 14);
            // Боковые фланцы для крепления
            translate([-(motor_d+14)/2-4, -flange_w/2, h/2-5])
                cube([motor_d+14+8, flange_w, 10]);
        }
        translate([0,0,-1]) cylinder(h=h+2, d=motor_d+1);
        translate([0,0,h]) cylinder(h=shaft_l+4, d=shaft_d);
        // Крепёжные отверстия
        for(x=[-flange_w/2, flange_w/2], y=[-flange_w/2, flange_w/2])
            translate([x, y, h/2]) cylinder(h=12, d=3);
    }
}

// МОТОР 28BYJ-48
module stepper_28byj48() {
    color("dimgray")
    difference() {
        cylinder(h=motor_h, d=motor_d);
        translate([0,0,motor_h-1]) cylinder(h=shaft_l+2, d=shaft_d);
    }
    color("silver")
    translate([0,0,motor_h]) cylinder(h=shaft_l, d=shaft_d);
    // Крепёжные выступы
    for(a=[0:90:359])
        rotate([0,0,a])
            translate([motor_d/2-2, 0, motor_h/2])
                cylinder(h=3, d=5);
}

// ULN2003
module uln2003() {
    color("green")
    difference() {
        cube([driver_w, driver_h, driver_th]);
        for(x=[-1,1], y=[-1,1])
            translate([driver_w/2+x*23/2, driver_h/2+y*15/2, -1])
                cylinder(h=driver_th+2, d=2.5);
    }
    color("black")
    translate([-driver_w/2+4, 0, driver_th])
        cube([8, 6, 3]);
}

// НИЖНЕЕ ПЛЕЧО — облегчённое с рёбрами жесткости
module lower_arm() {
    color("gold")
    difference() {
        translate([0, 0, lower_arm_t/2])
            cube([lower_arm_l, lower_arm_w, lower_arm_t], center=true);
        // Вырез под мотор на конце плеча
        translate([lower_arm_l/2-15, 0, -1])
            cylinder(h=lower_arm_t+4, d=motor_d+5);
        // Сотовые облегчения
        for(i=[-1,0,1])
            translate([i*lower_arm_l/4, 0, lower_arm_t/2])
                cube([lower_arm_l/6, lower_arm_w/2.5, lower_arm_t+2], center=true);
    }
    // Рёбра жёсткости
    translate([-lower_arm_l/2+8, lower_arm_w/2-3, lower_arm_t/2])
        cube([18, 6, lower_arm_t+8]);
    translate([-lower_arm_l/2+8, -lower_arm_w/2+3, lower_arm_t/2])
        cube([18, 6, lower_arm_t+8]);
    // Ось сустава (внутри плеча, несёт нагрузку)
    translate([-lower_arm_l/2+5, 0, lower_arm_t/2])
        cylinder(h=lower_arm_w+12, d=10);
}

// ВЕРХНЕЕ ПЛЕЧО — легче нижнего
module upper_arm() {
    color("gold")
    difference() {
        translate([0, 0, upper_arm_t/2])
            cube([upper_arm_l, upper_arm_w, upper_arm_t], center=true);
        translate([upper_arm_l/2-12, 0, -1])
            cylinder(h=upper_arm_t+4, d=motor_d+3);
        for(i=[-1,0,1])
            translate([i*upper_arm_l/4, 0, upper_arm_t/2])
                cube([upper_arm_l/6, upper_arm_w/2.5, upper_arm_t+2], center=true);
    }
    translate([-upper_arm_l/2+6, upper_arm_w/2-2.5, upper_arm_t/2])
        cube([14, 5, upper_arm_t+6]);
    translate([-upper_arm_l/2+6, -upper_arm_w/2+2.5, upper_arm_t/2])
        cube([14, 5, upper_arm_t+6]);
    translate([-upper_arm_l/2+4, 0, upper_arm_t/2])
        cylinder(h=upper_arm_w+8, d=8);
}

// УНИВЕРСАЛЬНАЯ ПЛАТФОРМА — крепление для паяльника/насадок
module tool_mount() {
    color("silver")
    difference() {
        cube([plate_w, plate_d, 8]);
        // 4 крепёжных отверстия
        for(x=[-mount_sp/2, mount_sp/2], y=[-mount_sp/2, mount_sp/2])
            translate([plate_w/2+x, plate_d/2+y, -1])
                cylinder(h=10, d=4);
        // Центральное отверстие
        translate([0, 0, -1])
            cylinder(h=12, d=8);
    }
    // Резьбовые втулки
    color("dimgray")
    for(x=[-mount_sp/2, mount_sp/2], y=[-mount_sp/2, mount_sp/2])
        translate([plate_w/2+x, plate_d/2+y, 8])
            cylinder(h=8, d=6);
}

// ========== СБОРКА ==========
// База
translate([0, 0, 0]) base();

// Мотор вращения базы
translate([0, 0, base_h+2]) motor_holder(22);
translate([0, 0, base_h+24]) stepper_28byj48();

// Плата ULN2003 на стенке
translate([-(base_d/2+driver_w/2+2), 0, base_h/2])
    rotate([0, 90, 0]) uln2003();

// Нижнее плечо
translate([0, 0, base_h+24+motor_h+6]) lower_arm();

// Мотор локтя
translate([lower_arm_l/2-5, 0, base_h+24+motor_h+6])
    motor_holder(18);
translate([lower_arm_l/2-5, 0, base_h+24+motor_h+6+18])
    stepper_28byj48();

// Верхнее плечо
translate([lower_arm_l/2-5, 0, base_h+24+motor_h+6+18+motor_h+5])
    upper_arm();

// Платформа для насадок
translate([lower_arm_l/2-5+upper_arm_l/2-5, 0,
           base_h+24+motor_h+6+18+motor_h+5])
    tool_mount();

// ========== ДЛЯ ПЕЧАТИ (раскомментируй) ==========
