// Robot Arm v5.0 — ПРАВИЛЬНАЯ КИНЕМАТИКА
// Моторы ИНТЕГРИРОВАНЫ в суставы, не торчат наружу
// 28BYJ-48 + ULN2003

motor_d = 28;
motor_h = 19;
shaft_d = 5;
shaft_l = 10;

// Оси (в мм)
axis_d = 8;      // диаметр осей суставов
axis_l = 35;     // длина оси (насквозь через плечо)

// Основание — цилиндр с интегрированным мотором
base_h = 50;
base_d = 65;
turntable_d = 55;

// Плечи — трубчатая конструкция
lower_arm_d = 30;   // внешний диаметр "трубы" нижнего плеча
lower_arm_l = 70;
upper_arm_d = 25;
upper_arm_l = 55;

// Крышки суставов (купольные)
cap_d = 35;
cap_h = 8;

$fn = 100;

// ========== ОСНОВАНИЕ ==========
module base() {
    // Неподвижное основание — цилиндр
    color("silver")
    difference() {
        cylinder(h=base_h, d=base_d);
        // Вырез снизу
        translate([0,0,5])
            cylinder(h=base_h/2, d=base_d-20);
        // Отверстие под ось вращения базы
        translate([0,0,base_h-10])
            cylinder(h=15, d=shaft_d+2);
    }

    // Платформа для плеча — тоже неподвижная
    color("dimgray")
    translate([0, 0, base_h])
        difference() {
            cylinder(h=15, d=turntable_d);
            translate([0,0,-1])
                cylinder(h=17, d=shaft_d+6);
            // Крепёж для мотора
            for(a=[0:90:359])
                rotate([0,0,a])
                    translate([15, 0, 7])
                        cylinder(h=10, d=3);
        }

    // Мотор вращения базы — СБОКУ в корпусе
    color("silver")
    translate([base_d/2-8, 0, base_h/2])
        difference() {
            cylinder(h=25, d=motor_d+12);
            translate([0,0,-1])
                cylinder(h=27, d=motor_d+1);
            translate([0,0,25])
                cylinder(h=shaft_l+3, d=shaft_d);
            for(x=[-10,10], y=[-10,10])
                translate([x,y,12.5])
                    cylinder(h=15, d=3);
        }
    // Сам мотор
    color("dimgray")
    translate([base_d/2-8, 0, base_h/2-13])
        difference() {
            cylinder(h=motor_h, d=motor_d);
            translate([0,0,motor_h-1])
                cylinder(h=shaft_l+2, d=shaft_d);
        }
}

// ========== НИЖНЕЕ ПЛЕЧО ==========
module lower_arm() {
    // Соединительная втулка (от базы к плечу)
    color("silver")
    translate([0,0,15])
        cylinder(h=25, d=axis_d+10);

    // Основная "труба" плеча — круглая в сечении
    color("silver")
    difference() {
        translate([0, 0, 25])
            cylinder(h=lower_arm_l, d=lower_arm_d);
        // Облегчение внутри
        translate([0,0,26])
            cylinder(h=lower_arm_l-2, d=lower_arm_d-8);
    }

    // Рёбра жёсткости на плече (снаружи)
    for(a=[0,120,240])
        rotate([0,0,a])
            translate([0, lower_arm_d/2-2, 30])
                cube([lower_arm_l-20, 4, 6], center=true);

    // Сустав локтя — на конце плеча
    color("dimgray")
    translate([0, 0, 25+lower_arm_l])
        difference() {
            cylinder(h=20, d=axis_d+14);
            translate([0,0,-1])
                cylinder(h=22, d=motor_d+2);
            translate([0,0,20])
                cylinder(h=shaft_l+3, d=shaft_d);
            for(x=[-8,8], y=[-8,8])
                translate([x,y,10])
                    cylinder(h=12, d=3);
        }
}

// ========== ВЕРХНЕЕ ПЛЕЧО ==========
module upper_arm() {
    // Втулка крепления к локтю
    color("silver")
    translate([0,0,-5])
        cylinder(h=15, d=axis_d+8);

    // "Труба" верхнего плеча
    color("silver")
    difference() {
        translate([0, 0, 5])
            cylinder(h=upper_arm_l, d=upper_arm_d);
        translate([0,0,6])
            cylinder(h=upper_arm_l-2, d=upper_arm_d-6);
    }

    // Рёбра
    for(a=[0,120,240])
        rotate([0,0,a])
            translate([0, upper_arm_d/2-2, 10])
                cube([upper_arm_l-15, 3, 5], center=true);

    // Мотор локтя — на суставе
    color("silver")
    translate([0, 0, 5+upper_arm_l])
        difference() {
            cylinder(h=22, d=motor_d+12);
            translate([0,0,-1])
                cylinder(h=24, d=motor_d+1);
            translate([0,0,22])
                cylinder(h=shaft_l+3, d=shaft_d);
            for(x=[-9,9], y=[-9,9])
                translate([x,y,11])
                    cylinder(h=14, d=3);
        }
    // Сам мотор
    color("dimgray")
    translate([0, 0, 5+upper_arm_l-12])
        difference() {
            cylinder(h=motor_h, d=motor_d);
            translate([0,0,motor_h-1])
                cylinder(h=shaft_l+2, d=shaft_d);
        }
}

// ========== КРЕПЛЕНИЕ ИНСТРУМЕНТА ==========
module tool_mount() {
    color("silver")
    difference() {
        cube([50, 50, 8]);
        for(x=[-19,19], y=[-19,19])
            translate([25+x, 25+y, -1])
                cylinder(h=10, d=4);
    }
    // Втулки
    color("dimgray")
    for(x=[-19,19], y=[-19,19])
        translate([25+x, 25+y, 8])
            cylinder(h=6, d=6);
}

// ========== СБОРКА ==========
// База
translate([0, 0, 0])
    base();

// Ось вращения — проходит через всю базу
translate([0, 0, base_h+10])
    cylinder(h=20, d=shaft_d+2);

// Нижнее плечо — поворачивается на оси
translate([0, 0, base_h+15])
    lower_arm();

// Верхнее плечо — поворачивается на локте
translate([0, 0, base_h+15+25+lower_arm_l+10])
    upper_arm();

// Платформа для инструментов
translate([0, 0, base_h+15+25+lower_arm_l+10+5+upper_arm_l+22])
    tool_mount();

